   449|  private async verifySupabaseTable(): Promise<boolean> {
   450|    if (this.supabaseTableVerified) return true;
   451|    if (this.supabaseTableMissing) {
   452|      if (this.tableCheckAttempts < this.MAX_TABLE_CHECK_ATTEMPTS * 3) {
   453|        this.tableCheckAttempts++;
   454|        if (this.tableCheckAttempts % 5 === 0) {
   455|          console.log('[Analytics] Re-checking table existence (attempt', this.tableCheckAttempts, ')');
   456|          this.supabaseTableMissing = false;
   457|        } else {
   458|          return false;
   459|        }
   460|      } else {
   461|        return false;
   462|      }
   463|    }
   464|
   465|    if (!isSupabaseConfigured()) {
   466|      console.error('[Analytics] Supabase not configured — events will not be persisted');
   467|      this.supabaseTableMissing = true;
   468|      this.lastSyncError = 'Supabase not configured';
   469|      return false;
   470|    }
   471|
   472|    this.tableCheckAttempts++;
   473|    try {
   474|      const { data, error } = await supabase.from('analytics_events').select('id').limit(1);
   475|      if (error) {
   476|        if (error.message?.includes('does not exist') || error.code === '42P01' || error.message?.includes('relation')) {
   477|          this.supabaseTableMissing = true;
   478|          console.warn('[Analytics] analytics_events table does not exist. Create it in Supabase.');
   479|          this.lastSyncError = 'analytics_events table missing';
   480|          return false;
   481|        }
   482|        console.log('[Analytics] Table check returned error (may be RLS — treating as exists):', error.message);
   483|        this.supabaseTableVerified = true;
   484|        return true;
   485|      }
   486|      this.supabaseTableVerified = true;
   487|      this.supabaseTableMissing = false;
   488|      if (data && data.length > 0) {
   489|        const { data: schemaCheck, error: schemaErr } = await supabase.from('analytics_events').select('id,name,category,platform').limit(1);
   490|        if (!schemaErr && schemaCheck && schemaCheck.length > 0) {
   491|          const row = schemaCheck[0] as Record<string, unknown>;
   492|          this.tableHasExtendedSchema = 'name' in row || 'category' in row || 'platform' in row;
   493|        } else {
   494|          this.tableHasExtendedSchema = false;
   495|        }
   496|        console.log('[Analytics] Table verified — schema:', this.tableHasExtendedSchema ? 'extended' : 'master');
   497|      } else {
   498|        console.log('[Analytics] Table exists but is empty — will try extended schema first');
   499|      }
   500|      return true;
   501|    } catch (err) {
   502|      console.log('[Analytics] Table verification error:', (err as Error)?.message);
   503|      return false;
   504|    }
   505|  }
