   517|  private async syncToSupabase(): Promise<void> {
   518|    if (this.supabasePendingQueue.length === 0) return;
   519|
   520|    if (this.supabasePendingQueue.length > MAX_PENDING_QUEUE) {
   521|      const overflow = this.supabasePendingQueue.slice(0, this.supabasePendingQueue.length - MAX_PENDING_QUEUE);
   522|      this.supabasePendingQueue = this.supabasePendingQueue.slice(-MAX_PENDING_QUEUE);
   523|      this.failoverToAWS(overflow, 'queue_overflow');
   524|      console.warn('[Analytics] Pending queue overflow — sent', overflow.length, 'events to AWS backup');
   525|    }
   526|
   527|    const userId = await this.getSupabaseUserId();
   528|
   529|    const tableExists = await this.verifySupabaseTable();
   530|    if (!tableExists) {
   531|      console.error('[Analytics] SYNC BLOCKED: analytics_events table missing. Pending:', this.supabasePendingQueue.length, 'events. These events are at risk of being lost.');
   532|      this.syncFailureCount++;
   533|      return;
   534|    }
   535|
   536|    const batch = this.supabasePendingQueue.splice(0, SUPABASE_BATCH_SIZE);
   537|    if (batch.length === 0) return;
   538|
   539|    try {
   540|      const effectiveUserId = userId || null;
   541|      const useExtended = this.tableHasExtendedSchema !== false;
   542|      const rows = batch.map(event => {
   543|        if (useExtended) {
   544|          return {
   545|            id: event.id,
   546|            user_id: effectiveUserId,
   547|            name: event.name,
   548|            category: event.category,
   549|            properties: event.properties ? JSON.stringify(event.properties) : null,
   550|            timestamp: new Date(event.timestamp).toISOString(),
   551|            session_id: event.sessionId,
   552|            platform: event.platform,
   553|          };
   554|        }
   555|        return {
   556|          event: event.name || event.category || 'unknown',
   557|          user_id: effectiveUserId,
   558|          properties: event.properties ? { ...event.properties, category: event.category, platform: event.platform } : { category: event.category, platform: event.platform },
   559|          session_id: event.sessionId,
   560|        };
   561|      });
   562|
   563|      console.log(`[Analytics] Attempting sync of ${rows.length} events (user: ${effectiveUserId ? effectiveUserId.substring(0, 8) : 'null'}, schema: ${useExtended ? 'extended' : 'master'})`);
   564|
   565|      let { error } = await supabase.from('analytics_events').insert(rows);
   566|
   567|      if (error && useExtended && (error.message?.includes('column') || error.code === '42703')) {
   568|        console.log('[Analytics] Extended schema failed, retrying with master schema...');
   569|        this.tableHasExtendedSchema = false;
   570|        const masterRows = batch.map(event => ({
   571|          event: event.name || event.category || 'unknown',
   572|          user_id: effectiveUserId,
   573|          properties: { ...(event.properties || {}), category: event.category, platform: event.platform },
   574|          session_id: event.sessionId,
   575|        }));
   576|        console.log('[Analytics] Retrying with master schema for', masterRows.length, 'events');
   577|        const retryResult = await supabase.from('analytics_events').insert(masterRows);
   578|        error = retryResult.error;
   579|      }
   580|
   581|      if (error && !effectiveUserId && (error.message?.includes('RLS') || error.code === '42501' || error.message?.includes('violates'))) {
   582|        console.log('[Analytics] RLS blocked anon insert — retrying via REST API with anon key...');
   583|        const restError = await this.syncBatchViaRest(batch, useExtended);
   584|        if (!restError) {
   585|          this.totalSynced += batch.length;
   586|          this.syncFailureCount = 0;
   587|          this.rlsFailureCount = 0;
   588|          this.lastSyncError = null;
   589|          this.resetSyncBackoff();
   590|          console.log(`[Analytics] REST fallback synced ${batch.length} events successfully`);
   591|          return;
   592|        }
   593|        error = { message: restError, details: '', hint: '', code: 'REST_FAIL' } as typeof error;
   594|      }
   595|
   596|      if (error) {
   597|        if (error.message?.includes('does not exist') || error.code === '42P01') {
   598|          this.supabaseTableMissing = true;
   599|          this.failoverToAWS(batch, 'table_missing');
   600|          console.log('[Analytics] analytics_events table missing — events sent to AWS backup');
   601|          return;
   602|        }
   603|        if (error.code === '23505') {
   604|          this.duplicateCount += batch.length;
   605|          console.log('[Analytics] Duplicate key — skipping batch. Total duplicates:', this.duplicateCount);
   606|          return;
   607|        }
   608|        if (!userId && (error.message?.includes('RLS') || error.code === '42501')) {
   609|          this.rlsFailureCount++;
   610|          this.syncFailureCount++;
   611|          this.lastSyncError = `RLS blocked: ${error.message}`;
   612|          if (this.rlsFailureCount >= this.MAX_RLS_FAILURES) {
   613|            this.failoverToAWS(batch, 'rls_blocked');
   614|            console.warn('[Analytics] RLS blocked', this.rlsFailureCount, 'times — sent', batch.length, 'events to AWS backup (zero events dropped)');
   615|          } else {
   616|            this.supabasePendingQueue.unshift(...batch);
   617|            console.log('[Analytics] RLS blocked (attempt', this.rlsFailureCount, '/', this.MAX_RLS_FAILURES, ') — events re-queued');
   618|          }
   619|          this.increaseSyncBackoff();
   620|          return;
   621|        }
   622|        if (this.syncFailureCount >= 10) {
   623|          this.failoverToAWS(batch, 'persistent_failure');
   624|          console.warn('[Analytics] Supabase sync failed', this.syncFailureCount, 'times — sent', batch.length, 'events to AWS backup');
   625|          this.syncFailureCount++;
   626|          this.lastSyncError = error.message;
   627|          this.increaseSyncBackoff();
   628|        } else {
   629|          this.supabasePendingQueue.unshift(...batch);
   630|          this.syncFailureCount++;
   631|          this.lastSyncError = error.message;
   632|          this.increaseSyncBackoff();
   633|          console.log('[Analytics] Supabase sync FAILED (attempt', this.syncFailureCount, '):', error.message);
   634|        }
   635|      } else {
   636|        this.totalSynced += batch.length;
   637|        this.syncFailureCount = 0;
   638|        this.rlsFailureCount = 0;
   639|        this.lastSyncError = null;
   640|        this.resetSyncBackoff();
   641|        console.log(`[Analytics] Synced ${batch.length} events to Supabase (${this.supabasePendingQueue.length} remaining, ${this.totalSynced} total synced)`);
   642|      }
   643|    } catch (error) {
   644|      if (this.syncFailureCount >= 10) {
   645|        this.failoverToAWS(batch, 'exception_failover');
   646|        console.warn('[Analytics] Supabase exception after', this.syncFailureCount, 'failures — sent', batch.length, 'events to AWS backup');
   647|      } else {
   648|        this.supabasePendingQueue.unshift(...batch);
   649|      }
   650|      this.syncFailureCount++;
   651|      this.lastSyncError = (error as Error)?.message ?? 'Unknown sync error';
   652|      this.increaseSyncBackoff();
   653|      console.log('[Analytics] Supabase sync error (attempt', this.syncFailureCount, '):', error);
   654|    }
   655|  }
