   657|  private failoverToAWS(batch: AnalyticsEvent[], reason: string): void {
   658|    if (!awsAnalyticsBackup.isConfigured()) {
   659|      console.log(`[Analytics] AWS failover skipped (${reason}): no endpoint configured — ${batch.length} events stored locally`);
   660|      return;
   661|    }
   662|    const awsEvents = batch.map(event => ({
   663|      id: event.id,
   664|      event: event.name,
   665|      session_id: event.sessionId,
   666|      properties: event.properties,
   667|      ip_address: (event.properties?.ip_address as string) || undefined,
   668|      platform: event.platform,
   669|      source: 'app' as const,
   670|      timestamp: new Date(event.timestamp).toISOString(),
   671|      created_at: new Date(event.timestamp).toISOString(),
   672|    }));
   673|    awsAnalyticsBackup.enqueueSupabaseFailover(awsEvents);
   674|    console.log(`[Analytics] AWS FAILOVER (${reason}): ${batch.length} events routed to AWS backup`);
   675|  }
