   677|  private async syncBatchViaRest(batch: AnalyticsEvent[], useExtended: boolean): Promise<string | null> {
   678|    const supabaseUrl = (process.env.EXPO_PUBLIC_SUPABASE_URL || '').trim();
   679|    const supabaseKey = (process.env.EXPO_PUBLIC_SUPABASE_ANON_KEY || '').trim();
   680|    if (!supabaseUrl || !supabaseKey) return 'Supabase not configured for REST fallback';
   681|
   682|    try {
   683|      const rows = batch.map(event => {
   684|        if (useExtended) {
   685|          return {
   686|            id: event.id,
   687|            user_id: null,
   688|            name: event.name,
   689|            category: event.category,
   690|            properties: event.properties ? JSON.stringify(event.properties) : null,
   691|            timestamp: new Date(event.timestamp).toISOString(),
   692|            session_id: event.sessionId,
   693|            platform: event.platform,
   694|          };
   695|        }
   696|        return {
   697|          event: event.name || event.category || 'unknown',
   698|          user_id: null,
   699|          properties: { ...(event.properties || {}), category: event.category, platform: event.platform },
   700|          session_id: event.sessionId,
   701|        };
   702|      });
   703|
   704|      const resp = await fetch(`${supabaseUrl}/rest/v1/analytics_events`, {
   705|        method: 'POST',
   706|        headers: {
   707|          'apikey': supabaseKey,
   708|          'Authorization': `Bearer ${supabaseKey}`,
   709|          'Content-Type': 'application/json',
   710|          'Prefer': 'return=minimal',
   711|        },
   712|        body: JSON.stringify(rows),
   713|      });
   714|
   715|      if (!resp.ok) {
   716|        const body = await resp.text();
   717|        console.error('[Analytics] REST sync failed:', resp.status, body);
   718|        return `REST ${resp.status}: ${body.substring(0, 200)}`;
   719|      }
   720|
   721|      return null;
   722|    } catch (err) {
   723|      console.error('[Analytics] REST sync exception:', (err as Error)?.message);
   724|      return (err as Error)?.message ?? 'REST sync unknown error';
   725|    }
   726|  }
